```go
import "sync/atomic"

// CPU 레벨 원자성 보장:
// 메인 메모리 → CPU 캐시 → 레지스터

// ✅ Lock-Free 카운터
type AtomicCounter struct {
    value int64
}

func (c *AtomicCounter) Increment() {
    // atomic.AddInt64는 한 번의 CPU 명령어 (LOCK XADD)
    // 중단 불가능 (Atomic)
    atomic.AddInt64(&c.value, 1)
