    success := atomic.CompareAndSwapInt64(&x, 30, 40)
    // success = true, x = 40

    // 6️⃣ LoadAndStore (Go 1.20+)
    newVal := atomic.LoadAndStoreInt64(&x, 50)  // newVal = 40, x = 50

